    private int? DFS(TreeNode root, int key, int? val, bool isFloor, bool isCeil) {

        if(root == null) return val;
        if(root.data == key) return key;

        if(isFloor && root.data <= key && (val == null || root.data > val)) val = root.data;
        if(isCeil && root.data >= key && (val == null || root.data < val)) val = root.data;

        if(key < root.data) {
            val = DFS(root.left, key, val, isFloor, isCeil);
        }
        else {
            val = DFS(root.right, key, val, isFloor, isCeil);
        }

        return val;
    }
